27	// reportMu keeps report generation consistent.
28	var reportMu sync.Mutex
29	
30	func cleanNote(s string) string {
31		ws := regexp.MustCompile(`\s+`)
32		angle := regexp.MustCompile(`[<>]`)
33		s = angle.ReplaceAllString(s, "")
34		return strings.TrimSpace(ws.ReplaceAllString(s, " "))
35	}
36	
37	func uniqueSorted(items []string) []string {
38		var out []string
39		for _, it := range items {
40			seen := false
41			for _, o := range out {
42				if o == it {
43					seen = true
44					break
45				}
46			}
47			if !seen {
48				out = append(out, it)
49			}
50		}
51		sort.Strings(out)
52		return out
53	}
