62			r.Lines = append(r.Lines, ReportLine{OrderID: o.ID, Customer: u.Name, Amount: o.Amount, Note: cleanNote(o.Note), Tags: o.Tags})
63			r.Total += o.Amount
64			tags = append(tags, o.Tags...)
65			customers = append(customers, u.Name)
66		}
