1	package main
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// queryLatency simulates the round trip to the database for every store call.
10	const queryLatency = 100 * time.Microsecond
11	
12	type User struct {
13		ID   int
14		Name string
15	}
16	
17	type Order struct {
18		ID     int
19		UserID int
20		Amount int // cents
21		Tags   []string
22		Note   string
23	}
24	
25	// Store stands in for the database. Every method costs one round trip.
26	type Store struct {
27		mu     sync.RWMutex
28		users  map[int]User
29		orders []Order
30	}
31	
32	func NewStore(nUsers, nOrders int) *Store {
33		s := &Store{users: map[int]User{}}
34		for i := 1; i <= nUsers; i++ {
35			s.users[i] = User{ID: i, Name: fmt.Sprintf("User %03d", i)}
36		}
37		tags := []string{"gift", "express", "bulk", "promo", "fragile", "intl", "retail", "b2b"}
38		for i := 1; i <= nOrders; i++ {
39			s.orders = append(s.orders, Order{
40				ID:     i,
41				UserID: 1 + (i*7)%nUsers,
42				Amount: 100 + (i*37)%9900,
43				Tags:   []string{tags[i%len(tags)], tags[(i*3)%len(tags)], tags[(i*5)%len(tags)]},
44				Note:   fmt.Sprintf("  order #%d <for> customer\t%d  ", i, i%13),
45			})
46		}
47		return s
48	}
49	
50	func (s *Store) roundTrip() { time.Sleep(queryLatency) }
51	
52	// ListOrders returns every order.
53	func (s *Store) ListOrders() []Order {
54		s.roundTrip()
55		s.mu.RLock()
56		defer s.mu.RUnlock()
57		out := make([]Order, len(s.orders))
58		copy(out, s.orders)
59		return out
60	}
61	
62	// GetUser returns one user.
63	func (s *Store) GetUser(id int) (User, bool) {
64		s.roundTrip()
65		s.mu.RLock()
66		defer s.mu.RUnlock()
67		u, ok := s.users[id]
68		return u, ok
69	}
70	
71	// GetUsers returns the users with the given ids in one round trip.
72	func (s *Store) GetUsers(ids []int) map[int]User {
73		s.roundTrip()
74		s.mu.RLock()
75		defer s.mu.RUnlock()
76		out := make(map[int]User, len(ids))
77		for _, id := range ids {
78			if u, ok := s.users[id]; ok {
79				out[id] = u
80			}
81		}
82		return out
83	}
